using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Data;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Animation;
using System.Xml.Linq;
using PZWorkshopDownloader.Models;
using PZWorkshopDownloader.Services;

namespace PZWorkshopDownloader;

public partial class MainWindow : Window
{
    private const string WorkshopHomeUrl =
        "https://steamcommunity.com/workshop/browse/?appid=" + SteamCmdService.AppId +
        "&browsesort=trend&section=readytouseitems";

    private readonly AppSettings _settings;
    private readonly ObservableCollection<QueueItem> _queue = new();
    private readonly ObservableCollection<ModRecord> _downloadedMods = new();
    private readonly ObservableCollection<DownloadTask> _downloads = new();
    private readonly ObservableCollection<UninstalledModEntry> _uninstalledMods = new();

    // Per-session cache of "Show Deps" Workshop-page lookups (workshopId ->
    // parsed required items), so re-opening the popup for the same mod doesn't
    // re-download the page. The in-flight set prevents duplicate simultaneous
    // fetches if the button is clicked repeatedly.
    private readonly Dictionary<string, List<WorkshopRequiredItem>> _depsPageCache = new();
    private readonly HashSet<string> _depsFetchInFlight = new();

    // ================= Batch 4: visual subsystem =================
    // Currently selected tag filters for the Installed Mods sidebar.
    private readonly HashSet<string> _selectedTags = new(StringComparer.OrdinalIgnoreCase);

    // Guards the thumbnail download fan-out so a large mod list doesn't
    // hammer the CDN with hundreds of concurrent requests.
    private static readonly SemaphoreSlim ThumbnailGate = new(4);

    private bool _tagSidebarExpanded = true;

    public MainWindow()
    {
        InitializeComponent();

        _settings = SettingsService.Load();

        QueueList.ItemsSource = _queue;
        _queue.CollectionChanged += (_, _) => UpdateQueuePanelVisibility();
        UpdateQueuePanelVisibility();
        DownloadedModsGrid.ItemsSource = _downloadedMods;
        foreach (var e in DownloadHistoryStore.Load())
        {
            _downloads.Add(new DownloadTask
            {
                Id = e.Id,
                Title = e.Title,
                Status = e.Status,
                Detail = e.Detail,
                StartedAt = e.StartedAt,
                FinishedAt = e.FinishedAt,
            });
        }
        DownloadsGrid.ItemsSource = _downloads;

        foreach (var entry in UninstalledModsStore.Load()) _uninstalledMods.Add(entry);
        UninstalledModsGrid.ItemsSource = _uninstalledMods;

        LogList.ItemsSource = _logEntries;

        // Batch 4: default tile size and shared views. Tiles bind to the same
        // collections as the grids, so the tag filter applies to both.
        Application.Current.Resources["ModTileSize"] = 140d;
        InstalledTiles.ItemsSource = _downloadedMods;
        DownloadsTiles.ItemsSource = _downloads;
        UninstalledTiles.ItemsSource = _uninstalledMods;

        // Fetch previews/tags + thumbnails for history and uninstalled lists
        // in the background; the grid/tile placeholders fill in as they arrive.
        _ = LoadDownloadsThumbnailsAsync();
        _ = LoadUninstalledThumbnailsAsync();

        PzFolderBox.Text = _settings.ModsFolder;
        DestFolderLabel.Text = string.IsNullOrWhiteSpace(_settings.ModsFolder) ? "Not set" : _settings.ModsFolder;
        BackupCheckbox.IsChecked = _settings.BackupUpdatedMods;
        AutoRefreshCheckbox.IsChecked = _settings.AutoRefreshOnTabSwitch;
        DebugLoggingCheckbox.IsChecked = _settings.DebugLogging;
        ThemeCombo.SelectedIndex = _settings.Theme switch
        {
            "Light" => 0,
            "Dark" => 1,
            "Midnight" => 2,
            "Forest" => 3,
            "Nord" => 4,
            "Dracula" => 5,
            "Solarized Dark" => 6,
            "Solarized Light" => 7,
            "Gruvbox" => 8,
            "Monokai" => 9,
            _ => 1,
        };
        ApplyTheme(_settings.Theme);

        ApplyUiFontSizes();

        Browser.SourceChanged += (_, _) => AddressBar.Text = Browser.Source?.ToString() ?? "";
        MainTabs.SelectionChanged += MainTabs_SelectionChanged;

        Loaded += MainWindow_Loaded;
    }

    private void MainTabs_SelectionChanged(object sender, System.Windows.Controls.SelectionChangedEventArgs e)
    {
        if (_settings.AutoRefreshOnTabSwitch && MainTabs.SelectedItem == InstalledModsTabItem)
            _ = RefreshDownloadedModsAsync();
    }

    private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        AppendLog("Application started.");
        try
        {
            await Browser.EnsureCoreWebView2Async();
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                "Could not start the embedded browser (WebView2). Make sure the " +
                "WebView2 Runtime is installed.\n\n" + ex.Message,
                "Browser init failed", MessageBoxButton.OK, MessageBoxImage.Warning);
            AppendLog($"Browser init failed: {ex.Message}");
        }

        await RefreshDownloadedModsAsync();
    }

    // ================= Bottom log panel =================

    private readonly ObservableCollection<LogEntry> _logEntries = new();
    private bool _logExpanded = false;

    private void ToggleLog_Click(object sender, RoutedEventArgs e)
    {
        _logExpanded = !_logExpanded;
        LogToggle.Content = _logExpanded ? "Hide Log \u25BC" : "Show Log \u25B2";

        var anim = new DoubleAnimation
        {
            To = _logExpanded ? 260 : 0,
            Duration = TimeSpan.FromMilliseconds(220),
            EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseInOut },
        };
        LogPanelBorder.BeginAnimation(HeightProperty, anim);
    }

    private void ClearLogButton_Click(object sender, RoutedEventArgs e)
    {
        _logEntries.Clear();
        JumpToBottomButton.Visibility = Visibility.Collapsed;
    }

    private void JumpToBottomButton_Click(object sender, RoutedEventArgs e)
    {
        if (_logEntries.Count > 0) LogList.ScrollIntoView(_logEntries[_logEntries.Count - 1]);
        JumpToBottomButton.Visibility = Visibility.Collapsed;
    }

    private bool IsLogAtBottom()
    {
        var sv = FindScrollViewer(LogList);
        if (sv == null) return true; // not rendered yet -- default to following
        return sv.ScrollableHeight <= 0 || sv.VerticalOffset >= sv.ScrollableHeight - 4;
    }

    private static ScrollViewer? FindScrollViewer(DependencyObject d)
    {
        for (int i = 0; i < VisualTreeHelper.GetChildrenCount(d); i++)
        {
            var child = VisualTreeHelper.GetChild(d, i);
            if (child is ScrollViewer sv) return sv;
            var result = FindScrollViewer(child);
            if (result != null) return result;
        }
        return null;
    }

    /// <summary>
    /// Appends a timestamped line to the in-app log panel so backend
    /// activity is visible without digging through any log file. Safe to
    /// call from any thread. DEBUG-level lines (raw, high-volume SteamCMD
    /// output) are skipped unless the debug logging setting is on. Only
    /// auto-scrolls if the user was already at the bottom -- otherwise a
    /// "Jump to Bottom" button appears instead of yanking their view.
    /// </summary>
    private void AppendLog(string message, string level = "INFO")
    {
        if (level == "DEBUG" && !_settings.DebugLogging) return;

        void Do()
        {
            bool wasAtBottom = IsLogAtBottom();

            _logEntries.Add(new LogEntry
            {
                Time = DateTime.Now.ToString("HH:mm:ss"),
                Level = level,
                Message = message,
            });
            while (_logEntries.Count > 500) _logEntries.RemoveAt(0);

            if (wasAtBottom)
            {
                LogList.UpdateLayout();
                if (_logEntries.Count > 0) LogList.ScrollIntoView(_logEntries[_logEntries.Count - 1]);
                JumpToBottomButton.Visibility = Visibility.Collapsed;
            }
            else
            {
                JumpToBottomButton.Visibility = Visibility.Visible;
            }
        }

        if (Dispatcher.CheckAccess()) Do();
        else Dispatcher.Invoke(Do);
    }

    // ================= Downloader tab: navigation =================

    private void Back_Click(object sender, RoutedEventArgs e)
    {
        if (Browser.CanGoBack) Browser.GoBack();
    }

    private void Forward_Click(object sender, RoutedEventArgs e)
    {
        if (Browser.CanGoForward) Browser.GoForward();
    }

    private void Home_Click(object sender, RoutedEventArgs e) => Navigate(WorkshopHomeUrl);

    private void AddressBar_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.Key == Key.Enter) Navigate(AddressBar.Text);
    }

    private void Navigate(string input)
    {
        input = input.Trim();
        if (string.IsNullOrEmpty(input)) return;

        string url = Regex.IsMatch(input, "^https?://", RegexOptions.IgnoreCase)
            ? input
            : $"https://steamcommunity.com/workshop/browse/?appid={SteamCmdService.AppId}&searchtext={Uri.EscapeDataString(input)}";

        if (Browser.CoreWebView2 != null)
            Browser.CoreWebView2.Navigate(url);
        else
            Browser.Source = new Uri(url);
    }

    private string? GetCurrentWorkshopId()
    {
        var url = Browser.Source?.ToString() ?? "";
        var m = Regex.Match(url, @"[?&]id=(\d+)");
        return m.Success ? m.Groups[1].Value : null;
    }

    private string GetCurrentTitle()
    {
        var t = Browser.CoreWebView2?.DocumentTitle ?? "";
        var idx = t.IndexOf("::", StringComparison.Ordinal);
        return (idx >= 0 ? t[(idx + 2)..] : t).Trim();
    }

    // ================= Downloader tab: download actions =================

    private void PickModsFolder()
    {
        var dlg = new Microsoft.Win32.OpenFolderDialog
        {
            InitialDirectory = string.IsNullOrWhiteSpace(_settings.ModsFolder) ? null : _settings.ModsFolder,
        };
        if (dlg.ShowDialog() == true)
        {
            _settings.ModsFolder = dlg.FolderName;
            SettingsService.Save(_settings);
            DestFolderLabel.Text = _settings.ModsFolder;
            PzFolderBox.Text = _settings.ModsFolder;
            AppendLog($"Mods folder set to: {_settings.ModsFolder}");
            _ = RefreshDownloadedModsAsync();
        }
    }

    private async void DownloadCurrent_Click(object sender, RoutedEventArgs e)
    {
        var id = GetCurrentWorkshopId();
        if (id == null)
        {
            MessageBox.Show("Open a specific Workshop item page first (click into a mod from the list).");
            return;
        }
        await StartDownloadAsync(id, GetCurrentTitle());
    }

    private void AddToQueue_Click(object sender, RoutedEventArgs e)
    {
        var id = GetCurrentWorkshopId();
        if (id == null)
        {
            MessageBox.Show("Open a specific Workshop item page first (click into a mod from the list).");
            return;
        }
        if (_queue.Any(q => q.Id == id)) return;
        _queue.Add(new QueueItem { Id = id, Title = GetCurrentTitle(), Status = "Queued" });
    }

    private void ClearQueue_Click(object sender, RoutedEventArgs e) => _queue.Clear();

    /// <summary>
    /// The queue panel is window-level (right side of every tab). It stays
    /// hidden while the queue is empty and appears automatically as soon as a
    /// mod is queued, disappearing again once the queue is cleared.
    /// </summary>
    private void UpdateQueuePanelVisibility()
    {
        bool hasItems = _queue.Count > 0;
        QueuePanel.Visibility = hasItems ? Visibility.Visible : Visibility.Collapsed;
        QueueColumn.Width = hasItems ? new GridLength(280) : new GridLength(0);
    }

    private async void StartQueue_Click(object sender, RoutedEventArgs e)
    {
        if (string.IsNullOrWhiteSpace(_settings.ModsFolder))
        {
            MessageBox.Show("Choose a destination folder first.");
            return;
        }
        foreach (var item in _queue.ToList())
        {
            item.Status = "Downloading...";
            var ok = await StartDownloadAsync(item.Id, item.Title, showFolderWarning: false);
            item.Status = ok ? "Done" : "Failed";
        }
        StatusText.Text = "Queue finished.";
        AppendLog("Download queue finished.");
    }

    /// <summary>Returns true on success.</summary>
    private async Task<bool> StartDownloadAsync(string id, string title, bool showFolderWarning = true)
    {
        if (string.IsNullOrWhiteSpace(_settings.ModsFolder))
        {
            if (showFolderWarning) MessageBox.Show("Choose a destination folder first.");
            return false;
        }

        var task = new DownloadTask
        {
            Id = id,
            Title = title,
            Status = "Downloading",
            StartedAt = DateTime.Now.ToString("h:mm:ss tt"),
        };
        _downloads.Insert(0, task);
        SaveDownloadHistory();

        // Batch 4: fetch this mod's preview thumbnail in the background so the
        // Downloads tab shows it even before a full history reload.
        _ = FetchTaskThumbnailAsync(task);

        StatusText.Text = $"Downloading {title}...";
        AppendLog($"Starting download: {title} ({id})");
        ProgressBarCtl.IsIndeterminate = true;
        try
        {
            var installedPaths = await SteamCmdService.DownloadModAsync(id, _settings.ModsFolder, line =>
            {
                // SteamCMD's output arrives on a background thread.
                Dispatcher.Invoke(() => task.Detail = line);
                AppendLog(line, "DEBUG");
            });

            // Record the content manifest id (not a date) as the "version"
            // we now have locally, so future update-checks compare like for like.
            try
            {
                var details = await WorkshopApiService.GetDetailsAsync(id);
                _settings.LocalModVersions[id] = details.ContentManifestId;
                _settings.InstallDates[id] = DateTimeOffset.Now.ToString("dd-MMM-yy h:mm:ss tt");
            }
            catch
            {
                // Offline right after downloading -- leave whatever version
                // was previously recorded (or none) rather than fail the download.
            }
            SettingsService.Save(_settings);

            task.Status = "Done";
            task.FinishedAt = DateTime.Now.ToString("h:mm:ss tt");
            task.Detail = installedPaths.Count == 1
                ? $"Installed to \"{Path.GetFileName(installedPaths[0])}\""
                : $"{installedPaths.Count} mod folders installed";

            StatusText.Text = installedPaths.Count == 1
                ? $"Done: {title}"
                : $"Done: {title} ({installedPaths.Count} mod folders installed)";
            AppendLog($"Finished: {title} \u2714 ({installedPaths.Count} folder(s))");
            SaveDownloadHistory();
            await RefreshDownloadedModsAsync();
            return true;
        }
        catch (Exception ex)
        {
            task.Status = "Failed";
            task.FinishedAt = DateTime.Now.ToString("h:mm:ss tt");
            task.Detail = ex.Message;
            StatusText.Text = $"Failed: {title} — {ex.Message}";
            AppendLog($"FAILED: {title} — {ex.Message}", "ERROR");
            SaveDownloadHistory();
            return false;
        }
        finally
        {
            ProgressBarCtl.IsIndeterminate = false;
        }
    }

    private void ClearFinishedDownloads_Click(object sender, RoutedEventArgs e)
    {
        foreach (var t in _downloads.Where(t => t.Status is "Done" or "Failed").ToList())
            _downloads.Remove(t);
        SaveDownloadHistory();
    }

    private void ClearAllDownloads_Click(object sender, RoutedEventArgs e)
    {
        _downloads.Clear();
        SaveDownloadHistory();
    }

    private void RemoveDownloadEntry_Click(object sender, RoutedEventArgs e)
    {
        if (sender is FrameworkElement fe && fe.Tag is DownloadTask task)
        {
            _downloads.Remove(task);
            SaveDownloadHistory();
        }
    }

    private void SaveDownloadHistory()
    {
        var entries = _downloads.Select(t => new DownloadHistoryEntry
        {
            Id = t.Id,
            Title = t.Title,
            Status = t.Status,
            Detail = t.Detail,
            StartedAt = t.StartedAt,
            FinishedAt = t.FinishedAt,
        }).ToList();
        DownloadHistoryStore.Save(entries);
    }

    /// <summary>
    /// Figures out which Steam Workshop id a local mod folder corresponds to.
    /// Tries the "&lt;id&gt; &lt;name&gt;" naming convention this app installs mods
    /// under first, then falls back to scanning any mod.info file inside for
    /// a purely-numeric id= line (some mods happen to use one).
    /// </summary>
    private static bool TryExtractWorkshopId(string folderPath, out string id)
    {
        id = "";
        var name = Path.GetFileName(folderPath);
        if (name.StartsWith("_")) return false; // skip internal folders like _backups

        var m = Regex.Match(name, @"^(\d+)");
        if (m.Success)
        {
            id = m.Groups[1].Value;
            return true;
        }

        try
        {
            foreach (var infoFile in Directory.EnumerateFiles(folderPath, "mod.info", SearchOption.AllDirectories))
            {
                foreach (var line in File.ReadAllLines(infoFile))
                {
                    var lm = Regex.Match(line.Trim(), @"^id\s*=\s*(\d+)\s*$", RegexOptions.IgnoreCase);
                    if (lm.Success)
                    {
                        id = lm.Groups[1].Value;
                        return true;
                    }
                }
            }
        }
        catch
        {
            // Unreadable folder -- treat as unresolvable.
        }

        return false;
    }

    /// <summary>
    /// Normalizes a mod identifier for dependency matching: lowercase, remove
    /// spaces and punctuation, so "NeatUI_Framework" == "neatui framework" ==
    /// "NeatUI Framework" when comparing require= values against installed
    /// mods' id=/name= fields.
    /// </summary>
    private static string NormalizeModIdentifier(string value)
    {
        var sb = new System.Text.StringBuilder(value.Length);
        foreach (var c in value)
        {
            if (char.IsLetterOrDigit(c)) sb.Append(char.ToLowerInvariant(c));
        }
        return sb.ToString();
    }

    // ================= Downloaded Mods tab =================

    private async void RefreshDownloadedMods_Click(object sender, RoutedEventArgs e) =>
        await RefreshDownloadedModsAsync();

    private void ExportModList_Click(object sender, RoutedEventArgs e)
    {
        if (_downloadedMods.Count == 0)
        {
            MessageBox.Show("No installed mods to export yet. Try 'Refresh Mod List' first.");
            return;
        }

        var dlg = new Microsoft.Win32.SaveFileDialog
        {
            Filter = "XML files (*.xml)|*.xml",
            FileName = "pz_mod_list.xml",
        };
        if (dlg.ShowDialog() != true) return;

        try
        {
            var root = new XElement("ModList",
                _downloadedMods.Select(m => new XElement("Mod",
                    new XElement("Name", m.ModName),
                    new XElement("WorkshopID", m.Id),
                    new XElement("Author", m.Creator),
                    new XElement("Link", $"https://steamcommunity.com/sharedfiles/filedetails/?id={m.Id}"))));
            new XDocument(root).Save(dlg.FileName);

            AppendLog($"Exported {_downloadedMods.Count} mod(s) to {dlg.FileName}");
            StatusText.Text = "Mod list exported.";
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not save file: {ex.Message}");
            AppendLog($"Export failed: {ex.Message}", "ERROR");
        }
    }

    private void ImportModList_Click(object sender, RoutedEventArgs e)
    {
        var dlg = new Microsoft.Win32.OpenFileDialog { Filter = "XML files (*.xml)|*.xml" };
        if (dlg.ShowDialog() != true) return;

        XDocument doc;
        try
        {
            doc = XDocument.Load(dlg.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not read XML file: {ex.Message}");
            AppendLog($"Import failed: {ex.Message}", "ERROR");
            return;
        }

        var installedIds = _downloadedMods.Select(m => m.Id).ToHashSet();
        int added = 0, skipped = 0;

        foreach (var modEl in doc.Root?.Elements("Mod") ?? Enumerable.Empty<XElement>())
        {
            var id = modEl.Element("WorkshopID")?.Value?.Trim();
            var name = modEl.Element("Name")?.Value?.Trim();
            if (string.IsNullOrEmpty(id)) continue;

            if (installedIds.Contains(id) || _queue.Any(q => q.Id == id))
            {
                skipped++;
                continue;
            }

            _queue.Add(new QueueItem { Id = id, Title = string.IsNullOrEmpty(name) ? id : name, Status = "Queued" });
            added++;
        }

        AppendLog($"Imported mod list from {dlg.FileName}: {added} added to queue, {skipped} skipped (already installed or queued).");
        MessageBox.Show(
            $"{added} mod(s) added to the download queue.\n{skipped} were already installed or queued and skipped.\n\n" +
            "Switch to the Browser tab and click 'Start Downloading All' in the queue panel to fetch them.",
            "Import Complete");
    }

    /// <summary>
    /// Scans the mods folder, pulls live details from Steam for each mod,
    /// and determines which ones need an update -- this single pass now
    /// covers both "list what's installed" and "check for updates" (the
    /// tabs used to be separate; merged so there's one source of truth).
    /// </summary>
    private async Task RefreshDownloadedModsAsync()
    {
        if (string.IsNullOrWhiteSpace(_settings.ModsFolder) || !Directory.Exists(_settings.ModsFolder))
            return;

        AppendLog("Refreshing mod list and checking for updates...");
        var records = new List<ModRecord>();
        int updatesAvailable = 0;

        // Build an index of every installed mod's declared identifiers (id=/name=
        // from its mod.info) -> real workshop id (the numeric folder prefix), plus
        // the set of installed workshop ids. This lets require= entries (numeric
        // ids or internal names like "\NeatUI_Framework") be resolved purely
        // against what is already on disk -- no extra Steam API calls.
        var installedWorkshopIds = new HashSet<string>(StringComparer.Ordinal);
        var identifierIndex = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var dir in Directory.GetDirectories(_settings.ModsFolder))
        {
            if (!TryExtractWorkshopId(dir, out var knownId)) continue;
            installedWorkshopIds.Add(knownId);
            foreach (var ident in SteamCmdService.GetModIdentifiers(dir))
            {
                var key = NormalizeModIdentifier(ident);
                if (key.Length > 0) identifierIndex.TryAdd(key, knownId);
            }
        }

        foreach (var dir in Directory.GetDirectories(_settings.ModsFolder))
        {
            if (!TryExtractWorkshopId(dir, out var id)) continue;
            var folderName = Path.GetFileName(dir);

            // Resolve require= entries against the installed-mod index above.
            var requires = SteamCmdService.GetRequiresFields(dir);
            var missingDeps = new List<string>();
            foreach (var req in requires)
            {
                bool met = long.TryParse(req, out _)
                    ? installedWorkshopIds.Contains(req)
                    : identifierIndex.TryGetValue(NormalizeModIdentifier(req), out _);
                if (!met) missingDeps.Add(req);
            }

            string title = folderName, posted = "", updated = "", steamVer = "Unknown", creator = "";
            bool resolvedRemote = false;
            try
            {
                var details = await WorkshopApiService.GetDetailsAsync(id);
                title = details.Title;
                posted = details.TimeCreated == default ? "" : details.TimeCreated.ToLocalTime().ToString("dd-MMM-yy h:mm:ss tt");
                updated = details.TimeUpdated == default ? "" : details.TimeUpdated.ToLocalTime().ToString("dd-MMM-yy h:mm:ss tt");
                steamVer = string.IsNullOrEmpty(details.ContentManifestId) ? "Unknown" : details.ContentManifestId;
                resolvedRemote = !string.IsNullOrEmpty(details.ContentManifestId);
                creator = details.Creator;
            }
            catch
            {
                // Offline, or the item was removed -- still show the folder by id.
            }

            var hasLocalVersion = _settings.LocalModVersions.TryGetValue(id, out var lv) && !string.IsNullOrEmpty(lv);
            var localVer = hasLocalVersion ? lv! : "Unknown";
            var installDate = _settings.InstallDates.TryGetValue(id, out var idate) ? idate : "";

            bool needsUpdate;
            if (!resolvedRemote)
                needsUpdate = false; // couldn't reach Steam -- don't false-flag
            else if (!hasLocalVersion)
                needsUpdate = true; // never tracked (e.g. placed manually) -- flag so the user can decide
            else
                needsUpdate = !string.Equals(lv, steamVer, StringComparison.Ordinal);

            if (needsUpdate) updatesAvailable++;

            records.Add(new ModRecord
            {
                Folder = folderName,
                FullPath = dir,
                Id = id,
                ModName = title,
                Size = FormatSize(GetDirectorySize(dir)),
                Posted = posted,
                Updated = updated,
                LocalVersion = localVer,
                SteamVersion = steamVer,
                InstallDate = installDate,
                NeedsUpdate = needsUpdate,
                StatusLabel = needsUpdate ? "Update Available" : "Updated",
                Creator = creator,
                Dependencies = requires,
                MissingDependencies = missingDeps,
                MissingDepsCount = missingDeps.Count,
            });
        }

        _downloadedMods.Clear();
        foreach (var r in records) _downloadedMods.Add(r);

        UpdatesAvailableText.Text = $"Mods with updates available: {updatesAvailable}";
        UpdateAllButton.IsEnabled = updatesAvailable > 0;
        AppendLog($"Refresh complete: {records.Count} mod(s) installed, {updatesAvailable} update(s) available.");

        // Batch 4: kick off the preview/tag/thumbnail fetch for installed mods
        // in the background. Tag sidebar + thumbnails fill in as it completes.
        _ = LoadInstalledVisualsAsync();
    }

    // ================= Batch 4: visual loading pipeline =================

    /// <summary>
    /// Fetches preview_url + tags for the installed mods in one batched API
    /// call, downloads any missing thumbnails into the cache (throttled), then
    /// rebuilds the tag sidebar. Runs in the background; grids/tiles update in
    /// place because ThumbnailPath raises PropertyChanged.
    /// </summary>
    private async Task LoadInstalledVisualsAsync()
    {
        try
        {
            var mods = _downloadedMods.ToList();
            if (mods.Count == 0) { RebuildTagSidebar(); return; }

            var visuals = await WorkshopVisualService.GetVisualsAsync(mods.Select(m => m.Id));

            await Task.WhenAll(mods.Select(async m =>
            {
                if (!visuals.TryGetValue(m.Id, out var v)) return;
                m.Tags = v.Tags;
                await ThumbnailGate.WaitAsync();
                try
                {
                    m.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(m.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));

            await Dispatcher.InvokeAsync(RebuildTagSidebar);
            AppendLog($"Loaded previews/tags for {mods.Count} installed mod(s).");
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load mod visuals: {ex.Message}", "WARNING");
        }
    }

    private async Task LoadDownloadsThumbnailsAsync()
    {
        try
        {
            var tasks = _downloads.Where(t => !string.IsNullOrEmpty(t.Id)).Select(t => t.Id).Distinct().ToList();
            if (tasks.Count == 0) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(tasks);

            await Task.WhenAll(_downloads.Select(async t =>
            {
                if (!visuals.TryGetValue(t.Id, out var v)) return;
                await ThumbnailGate.WaitAsync();
                try
                {
                    t.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(t.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load download thumbnails: {ex.Message}", "WARNING");
        }
    }

    /// <summary>
    /// Fetches a single download task's preview thumbnail (used right after a
    /// new download starts). Never throws.
    /// </summary>
    private async Task FetchTaskThumbnailAsync(DownloadTask task)
    {
        try
        {
            if (string.IsNullOrEmpty(task.Id)) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(new[] { task.Id });
            if (!visuals.TryGetValue(task.Id, out var v)) return;
            task.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(task.Id, v.PreviewUrl);
        }
        catch
        {
            // Thumbnails are cosmetic; a failure here must never disturb a download.
        }
    }

    private async Task LoadUninstalledThumbnailsAsync()
    {
        try
        {
            var entries = _uninstalledMods.ToList();
            if (entries.Count == 0) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(entries.Select(e => e.Id));

            await Task.WhenAll(entries.Select(async e =>
            {
                if (!visuals.TryGetValue(e.Id, out var v)) return;
                await ThumbnailGate.WaitAsync();
                try
                {
                    e.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(e.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load uninstalled-mod thumbnails: {ex.Message}", "WARNING");
        }
    }

    // ================= Batch 4: tag filter sidebar =================

    /// <summary>
    /// Rebuilds the Installed Mods tag sidebar from the union of Steam tags
    /// across installed mods, preserving whatever filters were already checked.
    /// </summary>
    private void RebuildTagSidebar()
    {
        var tags = _downloadedMods.SelectMany(m => m.Tags)
            .Where(t => !string.IsNullOrWhiteSpace(t))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(t => t, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var kept = _selectedTags.Where(t => tags.Contains(t, StringComparer.OrdinalIgnoreCase)).ToList();

        TagFilterPanel.Children.Clear();
        foreach (var tag in tags)
        {
            var cb = new CheckBox
            {
                Content = tag,
                Tag = tag,
                IsChecked = kept.Contains(tag, StringComparer.OrdinalIgnoreCase),
                Margin = new Thickness(0, 2, 0, 2),
            };
            cb.SetResourceReference(Control.ForegroundProperty, "FgText");
            cb.Checked += TagFilter_Changed;
            cb.Unchecked += TagFilter_Changed;
            TagFilterPanel.Children.Add(cb);
        }

        TagCountText.Text = $"{tags.Count} tag(s)";
        _selectedTags.Clear();
        foreach (var t in kept) _selectedTags.Add(t);
        ApplyInstalledTagFilter();
    }

    private void TagFilter_Changed(object? sender, RoutedEventArgs e)
    {
        if (sender is not CheckBox { Tag: string tag } cb) return;
        if (cb.IsChecked == true) _selectedTags.Add(tag);
        else _selectedTags.Remove(tag);
        ApplyInstalledTagFilter();
    }

    /// <summary>
    /// Filters the installed-mod collection through the shared collection view
    /// so the list grid AND the tile view update together. A mod is shown when
    /// no filters are selected, or when it matches any selected tag. Mods with
    /// no tag data stay visible so nothing gets hidden by accident.
    /// </summary>
    private void ApplyInstalledTagFilter()
    {
        var view = CollectionViewSource.GetDefaultView(_downloadedMods);
        view.Filter = _selectedTags.Count == 0 ? null :
            o => o is ModRecord m && (m.Tags.Count == 0 || m.Tags.Any(t => _selectedTags.Contains(t)));
    }

