    /// <summary>
    /// "Show Deps" button on an Installed Mods row. The Steam Workshop page for
    /// the selected mod is the authoritative source of its dependencies: the
    /// "Required items" section lists every dependency (workshop id + name),
    /// whether or not it's installed. So the popup is populated from that page
    /// and each entry is annotated installed/missing by comparing its workshop id
    /// against the installed-mod index.
    ///
    /// This lookup happens ONLY here, on explicit user action -- never during
    /// startup or the Installed Mods refresh -- and fetches ONLY this mod's page
    /// (no recursive dependency-page requests). Results are cached per session
    /// and concurrent duplicate clicks are ignored.
    /// </summary>
    private async void ShowDeps_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement fe || fe.Tag is not ModRecord mod) return;

        // Authoritative installed-workshop-id set for the installed/missing flag.
        var installedIds = _downloadedMods.Select(m => m.Id).ToHashSet(StringComparer.Ordinal);

        // Fetch ONLY this mod's page. Per-session cache avoids re-downloading;
        // the in-flight guard drops duplicate clicks while a fetch is running.
        List<WorkshopRequiredItem> pageItems;
        string? pageError = null;
        if (_depsPageCache.TryGetValue(mod.Id, out var cached))
        {
            pageItems = cached;
        }
        else if (!_depsFetchInFlight.Add(mod.Id))
        {
            AppendLog($"Dependency lookup for \"{mod.ModName}\" is already in progress; ignoring repeat click.", "WARNING");
            return;
        }
        else
        {
            try
            {
                pageItems = await WorkshopPageService.GetRequiredItemsAsync(mod.Id);
                _depsPageCache[mod.Id] = pageItems;
                if (pageItems.Count > 0)
                    AppendLog($"Loaded {pageItems.Count} required item link(s) from the Workshop page for \"{mod.ModName}\".");
            }
            catch (Exception ex)
            {
                pageItems = new List<WorkshopRequiredItem>();
                pageError = ex.Message;
                AppendLog($"Could not read required items from the Workshop page for \"{mod.ModName}\": {ex.Message}", "WARNING");
            }
            finally
            {
                _depsFetchInFlight.Remove(mod.Id);
            }
        }

        // The page is authoritative: show every required item, installed or not.
        var displays = new List<DepDisplay>();
        foreach (var pi in pageItems)
        {
            displays.Add(new DepDisplay
            {
                Identifier = pi.Id,
                Title = pi.Title,
                WorkshopId = pi.Id,
                IsMissing = !installedIds.Contains(pi.Id),
            });
        }

        // Safety net for mods whose Steam page has no "Required items" section:
        // fall back to mod.info require= resolution so locally-known deps still show.
        if (displays.Count == 0)
            displays = BuildModInfoDisplays(mod);

        var dlg = new DepsDialog(
            mod.ModName,
            displays,
            queueOne: d => AddDependencyToQueue(d),
            openPage: d => OpenDependencyPage(d))
        { Owner = this };

        if (pageError != null)
            dlg.ShowError($"Could not load the Workshop page for \"{mod.ModName}\":\n{pageError}\n\n" +
                          (displays.Count > 0 ? "Showing locally-known requirements instead." : ""));

        dlg.ShowDialog();
    }

    /// <summary>
    /// Fallback used when the Workshop page has no required-items section:
    /// resolves the mod.info require= entries against installed mods'
    /// id=/name= identifiers (numeric entries are already workshop ids).
    /// </summary>
    private List<DepDisplay> BuildModInfoDisplays(ModRecord mod)
    {
        var installedIndex = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var installed in _downloadedMods)
        {
            foreach (var ident in SteamCmdService.GetModIdentifiers(installed.FullPath))
            {
                var key = NormalizeModIdentifier(ident);
                if (key.Length > 0) installedIndex.TryAdd(key, installed.Id);
            }
        }

        var displays = new List<DepDisplay>();
        foreach (var req in mod.Dependencies)
        {
            string? wsId = null;
            string title = req;

            if (long.TryParse(req, out _))
            {
                wsId = req; // numeric require= is already the workshop id
                var installed = _downloadedMods.FirstOrDefault(m => m.Id == req);
                if (installed != null) title = installed.ModName;
            }
            else
            {
                var key = NormalizeModIdentifier(req);
                if (installedIndex.TryGetValue(key, out var localId))
                {
                    wsId = localId; // matched against an installed mod
                    var installed = _downloadedMods.FirstOrDefault(m => m.Id == localId);
                    if (installed != null) title = installed.ModName;
                }
            }

            displays.Add(new DepDisplay
            {
                Identifier = req,
                Title = title,
                WorkshopId = wsId,
                IsMissing = wsId == null || !_downloadedMods.Any(m => m.Id == wsId),
            });
        }
        return displays;
    }

    private void AddDependencyToQueue(DepDisplay d)
    {
        if (d.WorkshopId == null) return;
        if (_queue.Any(q => q.Id == d.WorkshopId)) return;
        _queue.Add(new QueueItem { Id = d.WorkshopId, Title = d.Title, Status = "Queued" });
        AppendLog($"Queued dependency: {d.Title} ({d.WorkshopId})");
    }

    private void OpenDependencyPage(DepDisplay d)
    {
        if (d.WorkshopId != null)
        {
            Navigate($"https://steamcommunity.com/sharedfiles/filedetails/?id={d.WorkshopId}");
        }
        else
        {
            // No known id -- search Steam for the identifier instead.
            Navigate($"https://steamcommunity.com/workshop/browse/?appid={SteamCmdService.AppId}&searchtext=" +
                     Uri.EscapeDataString(d.Identifier));
        }
        MainTabs.SelectedItem = BrowserTabItem;
    }

    /// <summary>
    /// Shared by both the per-row Update button (only shown when a mod
    /// actually needs updating) and the always-visible Force Redownload
    /// button -- both do the same underlying operation, just gated
    /// differently in the UI.
    /// </summary>
    private async Task ForceRedownloadAsync(ModRecord mod, string logVerb)
    {
        if (_settings.BackupUpdatedMods) BackupMod(mod.Folder);
        RemoveOldModFolder(mod.Folder);
        AppendLog($"{logVerb}: {mod.ModName}");
        await StartDownloadAsync(mod.Id, mod.ModName, showFolderWarning: false);
        await RefreshDownloadedModsAsync();
    }

    private void UninstallMod_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement fe || fe.Tag is not ModRecord mod) return;

        var confirm = MessageBox.Show(
            $"Uninstall \"{mod.ModName}\"?\n\nThe mod folder will be deleted. " +
            "You can reinstall it later from the Uninstalled Mods tab.",
            "Confirm Uninstall", MessageBoxButton.YesNo, MessageBoxImage.Warning);
        if (confirm != MessageBoxResult.Yes) return;

        try
        {
            var path = Path.Combine(_settings.ModsFolder, mod.Folder);
            if (Directory.Exists(path)) Directory.Delete(path, recursive: true);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not delete folder: {ex.Message}");
            AppendLog($"FAILED to uninstall {mod.ModName}: {ex.Message}", "ERROR");
            return;
        }

        _uninstalledMods.Insert(0, new UninstalledModEntry
        {
            Id = mod.Id,
            ModName = mod.ModName,
            Author = mod.Creator,
            UninstallDate = DateTime.Now.ToString("dd-MMM-yy h:mm:ss tt"),
        });
        UninstalledModsStore.Save(_uninstalledMods.ToList());

        AppendLog($"Uninstalled: {mod.ModName}");
        StatusText.Text = $"Uninstalled: {mod.ModName}";
        _ = RefreshDownloadedModsAsync();
    }

    private async void ReinstallMod_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement fe || fe.Tag is not UninstalledModEntry entry) return;

        AppendLog($"Reinstalling: {entry.ModName}");
        var ok = await StartDownloadAsync(entry.Id, entry.ModName);
        if (ok)
        {
            _uninstalledMods.Remove(entry);
            UninstalledModsStore.Save(_uninstalledMods.ToList());
        }
    }

    private void ForgetUninstalledMod_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement fe || fe.Tag is not UninstalledModEntry entry) return;
        _uninstalledMods.Remove(entry);
        UninstalledModsStore.Save(_uninstalledMods.ToList());

