using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace PZWorkshopDownloader.Services;

public class WorkshopRequiredItem
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
}

/// <summary>
/// Reads the Steam Workshop page HTML of a published item and extracts its
/// "Required items" section. The page for any mod lists links to every mod it
/// depends on (the user picks these links up from the real mod page), which is
/// the only place a name-only require= entry (e.g. "\NeatUI_Framework") can be
/// mapped back to a real numeric workshop id.
///
/// Best-effort parser: Steam's markup can shift, so failure here only means
/// name-only dependencies fall back to opening a Steam search instead of a
/// direct mod page -- never a crash.
/// </summary>
public static class WorkshopPageService
{
    private static readonly HttpClient Http = CreateClient();

    private static HttpClient CreateClient()
    {
        var c = new HttpClient { Timeout = TimeSpan.FromSeconds(20) };
        // Steam tends to serve plain HTTP responses to unknown clients; a
        // browser-like UA avoids odd redirects/blocks.
        c.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36");
        return c;
    }

    public static async Task<List<WorkshopRequiredItem>> GetRequiredItemsAsync(string workshopId)
    {
        var url = $"https://steamcommunity.com/sharedfiles/filedetails/?id={Uri.EscapeDataString(workshopId)}";
        var html = await Http.GetStringAsync(url);

        // Scope to the required-items container when present; otherwise fall
        // back to scanning the whole page (still better than nothing).
        int start = html.IndexOf("requiredItemsContainer", StringComparison.OrdinalIgnoreCase);
        var section = start >= 0
            ? html.Substring(start, Math.Min(20000, html.Length - start))
            : html;

        // Each dependency is an <a> wrapping a <div class="requiredItem">Title</div>:
        //   <a href="https://steamcommunity.com/workshop/filedetails/?id=3508537032" ...>
        //     <div class="requiredItem">NeatUI Framework [B42]</div>
        //   </a>
        var items = new List<WorkshopRequiredItem>();
        var matches = Regex.Matches(
            section,
            @"<a\s+href=""[^""]*filedetails/\?id=(\d+)""[^>]*>\s*<div[^>]*class=""requiredItem""[^>]*>\s*(.*?)\s*</div>",
            RegexOptions.Singleline);

        foreach (Match m in matches)
        {
            var id = m.Groups[1].Value;
            var title = Regex.Replace(m.Groups[2].Value, @"<[^>]+>", "").Trim();
            title = WebUtility.HtmlDecode(title);
            if (string.IsNullOrEmpty(title)) continue;
            if (items.Any(x => x.Id == id)) continue;
            items.Add(new WorkshopRequiredItem { Id = id, Title = title });
        }
        return items;
    }
}

