public static string GetContentPath(string workshopId) =>
        Path.Combine(SteamCmdDir, "steamapps", "workshop", "content", AppId, workshopId);

    /// <summary>
    /// Root of SteamCMD's downloaded Workshop cache for Project Zomboid.
    /// Clearing this deletes the cached mod contents only -- SteamCMD itself
    /// lives in SteamCmdDir and is untouched.
    /// </summary>
    public static string ContentCacheDir =>
        Path.Combine(SteamCmdDir, "steamapps", "workshop", "content", AppId);

private void SettingsCheckbox_Changed(object sender, RoutedEventArgs e)
    {
        if (!IsLoaded) return;
        _settings.BackupUpdatedMods = BackupCheckbox.IsChecked == true;
        _settings.AutoRefreshOnTabSwitch = AutoRefreshCheckbox.IsChecked == true;
        _settings.DebugLogging = DebugLoggingCheckbox.IsChecked == true;
        SettingsService.Save(_settings);
    }

    private void ClearWorkshopCache_Click(object sender, RoutedEventArgs e)
    {
        var cacheDir = SteamCmdService.ContentCacheDir;
        if (!Directory.Exists(cacheDir))
        {
            MessageBox.Show("No cached Workshop mods found.", "Workshop Cache",
                MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        int count = Directory.GetFileSystemEntries(cacheDir).Length;
        if (count == 0)
        {
            MessageBox.Show("The Workshop cache is already empty.", "Workshop Cache",
                MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        var confirm = MessageBox.Show(
            $"Delete the cached contents of {count} Workshop item(s)?\n\n{cacheDir}\n\n" +
            "Only the downloaded mod cache is removed -- SteamCMD itself is kept.",
            "Confirm Cache Clear", MessageBoxButton.YesNo, MessageBoxImage.Warning);
        if (confirm != MessageBoxResult.Yes) return;

        try
        {
            int deleted = 0;
            foreach (var entry in Directory.GetFileSystemEntries(cacheDir))
            {
                if (Directory.Exists(entry)) Directory.Delete(entry, recursive: true);
                else File.Delete(entry);
                deleted++;
            }
            AppendLog($"Cleared Workshop cache: {deleted} item(s) deleted.");
            StatusText.Text = $"Cleared {deleted} cached Workshop item(s).";
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not clear the Workshop cache: {ex.Message}");
            AppendLog($"FAILED to clear Workshop cache: {ex.Message}", "ERROR");
        }
    }

